int main(void) {
    unsigned rates[]={160,600,2000,4000,4800};
    for(unsigned k=0;k<5;k++) {
        unsigned rate=rates[k],steps=rate/2;
        control_reset(0);
        output(1,6,64,1500,250,9001);
        assert(co[6].duty==64);
        motion(1,0,0,0,0,steps,rate,10,750,0,0,0,9002);
        assert(cm.active && co[6].duty==64);
        output(1,6,65,1500,250,9003);
        assert(co[6].token==9001 && co[6].duty==64);
        while(cm.active){motion_tick();control_guard(mock_now);cooling_update();}
        assert(cm.phase==CM_DONE && cm.sent[3]==steps);
        assert(co[6].duty==64 && co[6].remaining>0);
        output(1,6,65,1500,250,9004);
        assert(co[6].token==9004 && co[6].duty==65);
        advance(1500);assert(co[6].duty==0);
    }
    puts("PASS actual R5: heated E windows at 160/600/2000/4000/4800 Hz, max750ms, renewal between windows, 1500ms expiry");
    return 0;
}
